 package retrydelay

-import "time"
+import (
+	"fmt"
+	"time"
+)

+// Delay computes an exponential backoff delay for a one-based attempt
+// number. Attempt 1 returns base, and each subsequent attempt doubles the
+// previous delay, saturating at maximum without overflowing time.Duration.
 func Delay(attempt int, base, maximum time.Duration) (time.Duration, error) {
-	return 0, nil
+	if attempt < 1 {
+		return 0, fmt.Errorf("retrydelay: attempt must be >= 1, got %d", attempt)
+	}
+	if base <= 0 {
+		return 0, fmt.Errorf("retrydelay: base must be positive, got %v", base)
+	}
+	if maximum <= 0 {
+		return 0, fmt.Errorf("retrydelay: maximum must be positive, got %v", maximum)
+	}
+	if base > maximum {
+		return 0, fmt.Errorf("retrydelay: base (%v) must not exceed maximum (%v)", base, maximum)
+	}
+
+	delay := base
+	for i := 1; i < attempt; i++ {
+		if delay > maximum/2 {
+			return maximum, nil
+		}
+		delay *= 2
+	}
+	if delay > maximum {
+		return maximum, nil
+	}
+	return delay, nil
 }
